    public static function has(?string $name): bool
    {
        return $name !== null && isset(self::ICONS[$name]);
    }

    public static function svg(string $name, string $class = ''): string
    {
        [$width, $height, $path] = self::ICONS[$name] ?? self::ICONS['link'];

        return sprintf(
            '<svg class="icon %s" viewBox="0 0 %d %d" style="width:%sem" aria-hidden="true" fill="currentColor"><path d="%s"/></svg>',
            e($class), $width, $height, round($width / $height, 4), $path
        );
    }
}
